solutions.naive:
class Solution:
    def rangeBitwiseAnd(self, left: int, right: int) -> int:
        ans = left
        for x in range(left + 1, right + 1):
            ans &= x
            if ans == 0:
                break
        return ans

solutions.better:
class Solution:
    def rangeBitwiseAnd(self, left: int, right: int) -> int:
        shifts = 0
        while left < right:
            left >>= 1
            right >>= 1
            shifts += 1
        return left << shifts

solutions.optimal:
class Solution:
    def rangeBitwiseAnd(self, left: int, right: int) -> int:
        while right > left:
            # Removes a low bit that cannot be part of the common prefix.
            right &= right - 1
        return right

